#!/usr/bin/env node
// Generates src/lib/bergamot/bundles.ts from scripts/bergamot/bergamot-pins.json
// (collected from the mirror's pinned revision by collect-pins.mjs). The
// generated file is the single source of truth for the Bergamot engine: the
// pinned model files per pair, the runtime pins, and the NLLB-code -> pair
// routing. Regenerate with: node scripts/bergamot/gen-bundles.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const pins = JSON.parse(readFileSync(join(HERE, "bergamot-pins.json"), "utf8"));

// The routing this engine serves: NLLB-200 code pair -> Bergamot pair key on
// the mirror. Serbian and Croatian to English share Firefox's released
// Serbo-Croatian (hbs) model; everything else is a dedicated pair.
const ROUTES = [
  ["eng_Latn", "hrv_Latn", "en-hr"],
  ["hrv_Latn", "eng_Latn", "hbs-en"],
  ["eng_Latn", "srp_Cyrl", "en-sr"],
  ["srp_Cyrl", "eng_Latn", "hbs-en"],
  ["eng_Latn", "nob_Latn", "en-nb"],
  ["nob_Latn", "eng_Latn", "nb-en"],
  ["eng_Latn", "bul_Cyrl", "en-bg"],
  ["bul_Cyrl", "eng_Latn", "bg-en"],
  ["eng_Latn", "ell_Grek", "en-el"],
  ["ell_Grek", "eng_Latn", "el-en"],
  ["ron_Latn", "eng_Latn", "ro-en"],
  ["eng_Latn", "pes_Arab", "en-fa"],
  ["pes_Arab", "eng_Latn", "fa-en"],
  ["eng_Latn", "cat_Latn", "en-ca"],
  ["cat_Latn", "eng_Latn", "ca-en"],
  ["eng_Latn", "zsm_Latn", "en-ms"],
  ["zsm_Latn", "eng_Latn", "ms-en"],
  ["eng_Latn", "vie_Latn", "en-vi"],
  ["vie_Latn", "eng_Latn", "vi-en"],
  ["eng_Latn", "ukr_Cyrl", "en-uk"],
  ["ukr_Cyrl", "eng_Latn", "uk-en"],
  ["eng_Latn", "jpn_Jpan", "en-ja"],
  ["jpn_Jpan", "eng_Latn", "ja-en"],
  ["eng_Latn", "tha_Thai", "en-th"],
  ["tha_Thai", "eng_Latn", "th-en"],
  ["eng_Latn", "tur_Latn", "en-tr"],
  ["tur_Latn", "eng_Latn", "tr-en"],
  ["afr_Latn", "eng_Latn", "af-en"],
  ["ind_Latn", "eng_Latn", "id-en"],
  ["rus_Cyrl", "eng_Latn", "ru-en"],
  ["kor_Hang", "eng_Latn", "ko-en"],
  ["eng_Latn", "zho_Hant", "en-zh-Hant"],
  ["zho_Hant", "eng_Latn", "zh-Hant-en"],
];

for (const [, , pair] of ROUTES) {
  if (!pins.pairs[pair] || pins.pairs[pair].length === 0) {
    throw new Error(`route pair ${pair} has no pins`);
  }
}

// Only the pairs the routing uses ship in the generated table; the research
// pins keep the full candidate inventory.
const used = new Set(ROUTES.map(([, , pair]) => pair));

const file = (f) => `    { name: ${JSON.stringify(f.name)}, bytes: ${f.bytes}, sha256: ${JSON.stringify(f.sha256)} },`;

const pairBlocks = [...used]
  .sort()
  .map((pair) => {
    const files = pins.pairs[pair];
    const total = files.reduce((s, f) => s + f.bytes, 0);
    return `  ${JSON.stringify(pair)}: {
    modelId: ${JSON.stringify(`midudev/firefox-translations/${pair}`)},
    totalBytes: ${total},
    files: [
${files.map(file).join("\n")}
    ],
  },`;
  })
  .join("\n");

const routeLines = ROUTES.map(([src, tgt, pair]) => `  ${JSON.stringify(`${src}|${tgt}`)}: ${JSON.stringify(pair)},`).join("\n");

const out = `/**
 * The pinned Bergamot model pairs and runtime. Files load straight from the
 * byte-for-byte Mozilla mirror (midudev/firefox-translations, MPL-2.0) at the
 * pinned revision; every file's SHA-256 is verified before the bytes are used
 * or cached, exactly like the IndicTrans2 bundles. GENERATED by
 * scripts/bergamot/gen-bundles.mjs from scripts/bergamot/bergamot-pins.json
 * (which collect-pins.mjs built from the pinned revision's own size and hash
 * headers); edit that pipeline, not this file, to move a pin.
 *
 * The models are Mozilla's Firefox Translations release set: int8-quantized
 * Marian student models (intgemm.alphas.bin) with a lexical shortlist and
 * SentencePiece vocabularies, 20-52 MB per direction. Croatian and Serbian to
 * English share the released Serbo-Croatian (hbs) model, exactly as Firefox
 * routes them. Fidelity was verified against Mozilla's own registry hashes
 * (see the P10 research notes in the worklog).
 */

/** The mirror repository and the pinned revision every file loads from. */
export const BERGAMOT_MIRROR = "midudev/firefox-translations";
export const BERGAMOT_REVISION = ${JSON.stringify(pins.revision)};

/** The self-hosted runtime (scripts/copy-bergamot.mjs copies it from the
 * MPL-2.0 npm package @mkljczk/bergamot-translator). Verified by SHA-256
 * before use; shared by every Bergamot pair, like /ort/ for the pipelines. */
export const BERGAMOT_RUNTIME = {
  glue: { name: "bergamot-translator-worker.js", bytes: 80474, sha256: ${JSON.stringify("bc2fc98d859845162817f9526c39eb1ca4805f7149dfebc0fbcda4d2af68e13c")} },
  wasm: { name: "bergamot-translator-worker.wasm", bytes: 5241884, sha256: ${JSON.stringify("735d4d95ede043c48f146b9a89336077f18885ad30b7e9a6a86c51a73ca02e7b")} },
};

export type BergamotPinnedFile = {
  name: string;
  bytes: number;
  sha256: string;
};

export type BergamotPair = {
  /** Stable model identity: "<mirror repo>/<pair>", also the cache key. */
  modelId: string;
  totalBytes: number;
  files: BergamotPinnedFile[];
};

export const BERGAMOT_PAIRS: Record<string, BergamotPair> = {
${pairBlocks}
};

/** The browser cache the verified files live in (runtime and models). */
export const BERGAMOT_CACHE = "pt-bergamot";

/** NLLB-200 code pair -> Bergamot pair key. */
const PAIR_ROUTES: Record<string, string> = {
${routeLines}
};

/** The Bergamot pair serving an NLLB-200 code pair, or null. */
export function bergamotPairFor(src: string, tgt: string): string | null {
  return PAIR_ROUTES[\`\${src}|\${tgt}\`] ?? null;
}

/** File URL of one pinned model file, at the pinned revision. */
export function bergamotFileUrl(pair: string, name: string): string {
  return \`https://huggingface.co/\${BERGAMOT_MIRROR}/resolve/\${BERGAMOT_REVISION}/\${pair}/\${name}\`;
}
`;

writeFileSync(join(HERE, "../../src/lib/bergamot/bundles.ts"), out);
console.log(`generated src/lib/bergamot/bundles.ts: ${used.size} pairs, ${ROUTES.length} routes`);
